const ELEMENT_PROP_KEYS = new Set(["theme","question","refusal","when","focusY","zoom","stagger","shutAt","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  question: "Want a peek?",
  refusal: "That’s all you get.",
  when: "The rest, Monday.",
  focusY: 0.5,
  zoom: 3.2,
